{
  "statements": [
    {
      "id": "3.5.1a",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT a driver towing a trailer cannot accelerate as quickly",
      "sources": [
        {
          "id": "m82",
          "quote": "You cannot accelerate as quickly when you are towing a trailer."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.5.1b",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT a driver towing a trailer needs [?more space] BECAUSE the length of the vehicle is much longer with a trailer attached",
      "sources": [
        {
          "id": "m82",
          "quote": "You also need more space because the length of your vehicle is much longer with a trailer attached."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "more space",
          "note": "No measure of space is given."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.5.1c",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"make sure\")",
      "text": "a driver towing a trailer SHOULD make sure the driver has [?enough time and room] to complete the pass WHEN the driver is about to pass a vehicle",
      "sources": [
        {
          "id": "m82",
          "quote": "Before you pass, make sure you have enough time and room to complete the pass."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "enough time and room",
          "note": "No measure of time or room is given."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.5.1d",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"allow\", \"Do not\")",
      "text": "a driver towing a trailer SHOULD allow [?more room] AND SHOULD NOT move back into the original lane [?too soon] WHEN the driver has passed a vehicle AND the driver is about to move back to the original lane BECAUSE a move back into the original lane [?too soon] can cause the trailer to sway and make it difficult to control",
      "sources": [
        {
          "id": "m82",
          "quote": "Once you have passed, allow more room before you move back to your lane. Do not cut back into the lane too soon. This can cause your trailer to sway and make it difficult to control."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "more room",
          "note": "No measure of room is given."
        },
        {
          "code": "J",
          "span": "too soon",
          "note": "No measure of time is given."
        },
        {
          "code": "J",
          "span": "too soon",
          "note": "No measure of time is given."
        }
      ],
      "links": [],
      "note": "The two commands after passing are joined because they share the same role and conditions; \"cut back into the lane\" is written as \"move back into the original lane\"."
    },
    {
      "id": "3.5.2a",
      "type": "PROCEDURE",
      "force": "ADVISORY",
      "force_from": "imperative steps",
      "text": "TO let the other vehicles pass WHEN the driver towing a trailer is holding up a line of traffic",
      "steps": [
        {
          "n": "1",
          "text": "signal",
          "sources": [
            "m83"
          ]
        },
        {
          "n": "2",
          "text": "pull over",
          "sources": [
            "m83"
          ]
        },
        {
          "n": "3",
          "text": "let the other vehicles pass",
          "sources": [
            "m83"
          ]
        }
      ],
      "sources": [
        {
          "id": "m83",
          "quote": "If you are holding up a line of traffic, signal, pull over and let the other vehicles pass."
        }
      ],
      "flags": [],
      "links": [],
      "note": "The serial commands are written as steps to keep their order."
    },
    {
      "id": "3.5.2b",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT fast-moving trucks and buses create a strong air disturbance behind them",
      "sources": [
        {
          "id": "m83",
          "quote": "Fast-moving trucks and buses create a strong air disturbance behind them."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.5.2c",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT the wall of wind behind a large bus or truck may whip the trailer of a driver towing a trailer to the side, pushing it out of control WHEN a large bus or truck passes the driver towing a trailer",
      "sources": [
        {
          "id": "m83",
          "quote": "If a large bus or truck passes you, the wall of wind behind it may whip your trailer to the side, pushing it out of control."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.5.2d",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"do not brake\", \"Carefully steer\")",
      "text": "a driver towing a trailer SHOULD NOT brake AND SHOULD [?carefully] steer the vehicle and the trailer back into position WHEN a large bus or truck passes the driver AND the wall of wind behind the large bus or truck whips the trailer to the side",
      "sources": [
        {
          "id": "m83",
          "quote": "If a large bus or truck passes you, the wall of wind behind it may whip your trailer to the side, pushing it out of control. When you experience this, do not brake. Carefully steer your vehicle and trailer back into position."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "carefully",
          "note": "No observable test for careful steering."
        }
      ],
      "links": [],
      "note": "\"This\" refers to the wall of wind from a large bus or truck whipping the trailer to the side."
    },
    {
      "id": "3.5.2e",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT a [?slight] increase in speed may help WHEN a large bus or truck passes the driver towing a trailer AND the wall of wind behind the large bus or truck whips the trailer to the side",
      "sources": [
        {
          "id": "m83",
          "quote": "If a large bus or truck passes you, the wall of wind behind it may whip your trailer to the side, pushing it out of control. When you experience this, do not brake. Carefully steer your vehicle and trailer back into position. A slight increase in speed may help."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "slight",
          "note": "No measure of speed increase is given."
        }
      ],
      "links": [],
      "note": "\"May help\" is a possibility, not a permission, so it is a FACT."
    }
  ]
}
